# ============================================================
# CHECK DATA LENGTH
# ============================================================

assert len(atcdt_nodes) == len(atcdt_time), \
    "ATC-DT node and time arrays have different lengths"

assert len(mlatc_nodes) == len(mlatc_time), \
    "MLATC node and time arrays have different lengths"


# ============================================================
# GROWTH ESTIMATES AND MEANS
# ============================================================

atcdt_nodes_array = np.asarray(atcdt_nodes, dtype=float)
atcdt_time_array = np.asarray(atcdt_time, dtype=float)
mlatc_nodes_array = np.asarray(mlatc_nodes, dtype=float)
mlatc_time_array = np.asarray(mlatc_time, dtype=float)

atcdt_slope, atcdt_intercept = np.polyfit(
    atcdt_nodes_array,
    atcdt_time_array,
    1
)

mlatc_log_slope, mlatc_log_intercept = np.polyfit(
    np.log(mlatc_nodes_array),
    mlatc_time_array,
    1
)

atcdt_growth = (
    atcdt_slope * atcdt_nodes_array
    + atcdt_intercept
)

mlatc_growth = (
    mlatc_log_slope * np.log(mlatc_nodes_array)
    + mlatc_log_intercept
)

print(f"Mean ATC-DT process time: {np.mean(atcdt_time_array):.6f} s")
print(f"Mean MLATC process time: {np.mean(mlatc_time_array):.6f} s")
print()
print(
    "ATC-DT linear estimate: "
    f"time = {atcdt_slope:.6e} * nodes + {atcdt_intercept:.6f}"
)
print(
    "MLATC logarithmic estimate: "
    f"time = {mlatc_log_slope:.6f} * ln(nodes) "
    f"+ {mlatc_log_intercept:.6f}"
)


# ============================================================
# PLOT
# ============================================================

plt.figure(figsize=(10, 6))

plt.plot(
    atcdt_nodes,
    atcdt_time,
    marker='o',
    markersize=3,
    linewidth=1.5,
    label='ATC-DT'
)

plt.plot(
    atcdt_nodes_array,
    atcdt_growth,
    linestyle='--',
    linewidth=2,
    label='ATC-DT linear fit'
)

plt.plot(
    mlatc_nodes,
    mlatc_time,
    marker='o',
    markersize=3,
    linewidth=1.5,
    label='MLATC'
)

plt.plot(
    mlatc_nodes_array,
    mlatc_growth,
    linestyle='--',
    linewidth=2,
    label='MLATC logarithmic fit'
)

plt.xlabel('Node Count')
plt.ylabel('Process Time (s)')
plt.title('Node Count vs Process Time')

plt.grid(True, alpha=0.3)
plt.legend()

plt.tight_layout()
plt.show()